const A = 5, B = 3, C = 3;
const threshold = 6;
const coalitions = [];
if (A >= threshold) coalitions.push("A");
if (B >= threshold) coalitions.push("B");
if (C >= threshold) coalitions.push("C");
if (A + B >= threshold && A < threshold && B < threshold) coalitions.push("A+B");
if (A + C >= threshold && A < threshold && C < threshold) coalitions.push("A+C");
if (B + C >= threshold && B < threshold && C < threshold) coalitions.push("B+C");
return coalitions.join(", ");
```

